// 主构造函数 + 集合表达式（C# 12）
public class Cart(ITaxCalculator tax)
{
    private readonly int[] _rates = [5, 10, 13];   // 集合表达式
    public decimal Total(decimal amount) => tax.Apply(amount);
}

